CREATE TABLE "BusinessAssessmentCycle" ("id" TEXT NOT NULL PRIMARY KEY,"year" INTEGER NOT NULL,"quarter" INTEGER NOT NULL,"name" TEXT NOT NULL,"departmentOrgNodeId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"totalKpiScore" REAL NOT NULL DEFAULT 6,"createdById" TEXT NOT NULL,"confirmedById" TEXT,"confirmedAt" DATETIME,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,"deletedAt" DATETIME);
