CREATE TABLE "BusinessAssessmentSubject" ("id" TEXT NOT NULL PRIMARY KEY,"cycleId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"scoringType" TEXT NOT NULL,"passingNumericScore" REAL,"requiredGradeCode" TEXT,"maxScore" REAL,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
