CREATE TABLE "BusinessAssessmentSummary" ("id" TEXT NOT NULL PRIMARY KEY,"cycleId" TEXT NOT NULL,"userId" TEXT NOT NULL,"subjectCount" INTEGER NOT NULL,"passedSubjectCount" INTEGER NOT NULL,"earnedScore" REAL NOT NULL,"maxScore" REAL NOT NULL DEFAULT 6,"isOverallPassed" BOOLEAN NOT NULL,"calculatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
